using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;
public partial class StructureControlOperations:RefCounted
{
    private readonly ActorDataOperations _data=new();private readonly ActorAnimationOperations _animation=new();private readonly ActorPropertyOperations _properties=new();private readonly StructureDefinitionOperations _structure=new();private readonly PhysicsGeometryOperations _geometry=new();
    private static Control Host(VBoxContainer owner)=>owner.Get("host").As<Control>();private static Resource Actor(VBoxContainer owner)=>owner.Get("actor").As<Resource>();private static RefCounted Model(VBoxContainer owner)=>Host(owner).Get("model").As<RefCounted>();private Settings Links(VBoxContainer owner)=>_data.get_value(Actor(owner),new StringName("structure_connections"),new Settings()).AsGodotDictionary();private static double Time(Resource actor){double time=actor.Get("animation_time").AsDouble();return double.IsNaN(time)?0:time;}
    private static GArray Keys(Settings values){var result=new GArray();foreach(var key in values.Keys)result.Add(key);return result;}
    public void setup(VBoxContainer owner,Control host,Resource actor){owner.Set("host",host);owner.Set("actor",actor);owner.Name="StructuralConnections";build(owner);var updater=new Callable(owner,"sync");owner.Set("_sync_callback",updater);host.Get("_updaters").AsGodotArray().Add(updater);}
    public Control? editor(VBoxContainer owner){foreach(var node in owner.GetTree().GetNodesInGroup("actor_timeline_editors"))if(node.Get("model").AsGodotObject()==Model(owner))return node as Control;return null;}
    public Transform3D pose(VBoxContainer owner,Resource actor){var view=editor(owner);return view!=null?view.Get("physics").AsGodotObject().Call("animated_world",actor.Get("id"),view.Get("canvas").AsGodotObject().Get("playhead"),false,new Settings()).AsTransform3D():new Transform3D(Basis.Identity,actor.Get("values").AsGodotDictionary().GetValueOrDefault("position",Vector3.Zero).AsVector3());}
    private long Signature(VBoxContainer owner,Settings links)=>GD.Hash(new GArray{Keys(links),links.GetValueOrDefault(owner.Get("selected"),new Settings()).AsGodotDictionary().GetValueOrDefault("type",0)});
    public void sync(VBoxContainer owner){if(!GodotObject.IsInstanceValid(owner)||!owner.IsInsideTree())return;if(owner.Get("signature").AsInt64()!=Signature(owner,Links(owner)))owner.CallDeferred("build");}
    public void exit_tree(VBoxContainer owner){var host=Host(owner);if(GodotObject.IsInstanceValid(host)){host.Get("_updaters").AsGodotArray().Remove(owner.Get("_sync_callback"));foreach(var callback in owner.Get("callbacks").AsGodotArray())host.Get("_updaters").AsGodotArray().Remove(callback);}}
    public void toggle(VBoxContainer owner,string id,string key,bool value,Control? parent)
    {
        parent??=owner;var row=new HBoxContainer();parent.AddChild(row);var button=new CheckBox{Text=key.Replace('_',' ').Capitalize(),ButtonPressed=value,SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};row.AddChild(button);button.Toggled+=next=>_structure.set_value(Model(owner),Actor(owner),id,key,next,false);var actor=Actor(owner);var path=new[]{"structure_connections",id,key};Host(owner).Call("_add_keyframe_button",row,actor,_properties.create(new StringName(key),button.Text,value,true),path,value);Host(owner).Get("_updaters").AsGodotArray().Add(Callable.From(()=>{if(!GodotObject.IsInstanceValid(button))return;var fallback=actor.Get("values").AsGodotDictionary()["structure_connections"].AsGodotDictionary().GetValueOrDefault(id,new Settings()).AsGodotDictionary().GetValueOrDefault(key,value);button.SetPressedNoSignal(_animation.sampled_value(actor,path,Time(actor),fallback).AsBool());}));
    }
    public void number(VBoxContainer owner,string id,string key,double value,Control? parent,int axis)
    {
        parent??=owner;var row=new HBoxContainer();parent.AddChild(row);string title=key switch{"breaking_force"=>"Breaking force (N)","breaking_torque"=>"Breaking torque (N·m)","stiffness"=>"Stiffness (N/m)","break_at"=>"Break at source time (−1: off)","orientation"=>"Orientation (degrees)",_=>key.Replace('_',' ').Capitalize()};if(axis>=0)title+=" "+new[]{"X","Y","Z"}[axis];var label=new Label{Text=title,SizeFlagsHorizontal=Control.SizeFlags.ExpandFill,TextOverrunBehavior=TextServer.OverrunBehavior.TrimEllipsis,TooltipText=title};row.AddChild(label);var actor=Actor(owner);var path=new[]{"structure_connections",id,key};Variant fallback=axis<0?Variant.From(value):Links(owner)[id].AsGodotDictionary()[key];if(axis<=0)Host(owner).Call("_add_keyframe_button",row,actor,_properties.create(new StringName(key),title,fallback,true),path,fallback);var field=new DragNumber();field.Name="Structure_"+key+(axis>=0?"_"+axis:"");field.AllowGreater=true;field.AllowLesser=key is "break_at" or "pivot" or "target_pivot" or "orientation";field.Step=.01;field.SetValueNoSignal(value);parent.AddChild(field);Settings before=new();Variant Convert(double next){if(axis<0)return next;var vector=_animation.sampled_value(actor,path,Time(actor),_animation.value_at_path(actor,path)).AsVector3();vector[axis]=(float)next;return vector;}field.Connect("interaction_started",Callable.From(()=>before=_data.copy_value(actor.Get("values")).AsGodotDictionary()));field.Connect("preview_changed",Callable.From<double>(next=>_structure.set_value(Model(owner),actor,id,key,Convert(next),true)));field.Connect("drag_committed",Callable.From<double>(next=>{var final=Convert(next);if(_data.animation_track(actor,path)==null)actor.Set("values",before);_structure.set_value(Model(owner),actor,id,key,final,false);}));field.Connect("drag_cancelled",Callable.From(()=>{actor.Set("values",before);actor.Get("animation_previews").AsGodotDictionary().Remove(string.Join(" / ",path));actor.EmitChanged();Model(owner).EmitSignal("changed");}));field.ValueChanged+=next=>_structure.set_value(Model(owner),actor,id,key,Convert(next),false);Host(owner).Get("_updaters").AsGodotArray().Add(Callable.From(()=>{if(!GodotObject.IsInstanceValid(field)||field.Get("dragging").AsBool())return;var sampled=_animation.sampled_value(actor,path,Time(actor),_animation.value_at_path(actor,path));if(sampled.VariantType!=Variant.Type.Nil)field.SetValueNoSignal(axis<0?sampled.AsDouble():sampled.AsVector3()[axis]);}));
    }
